import{_ as i,l,o as t,c as s,v as e,p as n,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"rootkit","description":"","frontmatter":{"title":"rootkit","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rootkits.md","filePath":"cs/rootkits.md","lastUpdated":1789023840000}'),c={name:"cs/rootkits.md"};function E(B,a,u,A,_,k){const r=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="rootkit" tabindex="-1">rootkit <a class="header-anchor" href="#rootkit" aria-label="Permalink to &quot;rootkit&quot;">​</a></h1><div class="epigraph"><p>rootkit 要的是隐瞒：改内核对象、拦截列举、住进引导。检测若只问用户态 API，看见的是它安排的剧场。信任应下沉到度量启动与带外取证。</p><footer>—— 据 Hoglund and Butler, *Rootkits*；对照 NIST SP 800-155 对 BIOS 完整性的讨论；seL4 对最小 TCB</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/malware-analysis">恶意软件</a>常仍在用户态。缺口是<strong>隐蔽与持久在更高特权</strong>。本课讲为何 API 不可信、检测要下沉，不给编写 rootkit 的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户态列举进程可被钩子过滤。内核或虚拟化 rootkit 改的是观察者本身。缺口是：完整性要从不可被目标改写的根度量（后课安全启动）。</p><h3 id="课程禁止实现" tabindex="-1">课程禁止实现 <a class="header-anchor" href="#课程禁止实现" aria-label="Permalink to &quot;课程禁止实现&quot;">​</a></h3><p>不教挂钩、不教隐藏模块。只讲防御观察点。</p><p><span class="marginnote">Hoglund and Butler 是历史技术书；本课当威胁模型引用。检测：交叉视图、内存取证、TPM 度量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照用户态 / 内核 / 引导。防御：安全启动链、内核模块签名、远程证明后课。下一课加固与混淆：防御方与恶意方都会用混淆，目标相反。</p>',12)),(t(),n(p,null,{default:o(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20USR%5B%22%E7%94%A8%E6%88%B7%E6%80%81%20API%22%5D%20--%3E%20LIE%5B%22%E5%8F%AF%E8%A2%AB%E9%92%A9%E5%AD%90%E6%92%92%E8%B0%8E%22%5D%0A%20%20KER%5B%22%E5%86%85%E6%A0%B8%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20CROSS%5B%22%E4%BA%A4%E5%8F%89%E8%A7%86%E5%9B%BE%20%2F%20%E5%8F%96%E8%AF%81%22%5D%0A%20%20BOOT%5B%22%E5%BC%95%E5%AF%BC%E5%AE%8C%E6%95%B4%E6%80%A7%22%5D%20--%3E%20ROOT%5B%22%E4%BF%A1%E4%BB%BB%E6%A0%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>特权一旦丢，同机自检变弱。下一课二进制加固与混淆：合法软件防篡改 vs 恶意软件抗分析——本课只站在防御与审计。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无 rootkit 源码。二进制加固与混淆下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恶意软件分析在用户态会碰到撒谎的 API。</li><li>rootkit 把观察者变成目标。</li><li>检测下沉到度量启动与带外。</li><li>下一课加固与混淆。</li><li>出处：Hoglund and Butler；NIST SP 800-155；对照 Klein et al. seL4。</li></ul>',8))])}const P=i(c,[["render",E]]);export{f as __pageData,P as default};
